<script setup lang="ts">
import { friendlyError } from '@lostsky/api/client'; import LsButton from '@lostsky/ui/components/LsButton.vue'; import LsField from '@lostsky/ui/components/LsField.vue'; import LsFormList from '@lostsky/ui/components/LsFormList.vue'; import LsInlineError from '@lostsky/ui/components/LsInlineError.vue'; import LsPageHeader from '@lostsky/ui/components/LsPageHeader.vue'; import LsFormActions from '@lostsky/ui/components/LsFormActions.vue'; import LsFormSection from '@lostsky/ui/components/LsFormSection.vue'; import LsSwitchField from '@lostsky/ui/components/LsSwitchField.vue'; import { feedback } from '@lostsky/ui/feedback'; import { useMutation,useQuery } from '@tanstack/vue-query'; import { NInput,NInputNumber,NSelect,useDialog } from 'naive-ui'; import { computed,reactive,watch } from 'vue'; import { useRoute,useRouter } from 'vue-router'; import { canManage,manageApi } from '../../lib'
type Item={key:string;service_id:number|null;quantity:number;valid_days:number};let seq=0;const make=():Item=>({key:`new-${++seq}`,service_id:null,quantity:1,valid_days:30});const route=useRoute();const router=useRouter();const dialog=useDialog();const id=computed(()=>Number(route.params.id||0));const editing=computed(()=>id.value>0);const form=reactive({name:'',is_active:1,services:[make()] as Item[]});const options=useQuery({queryKey:['manage-options'],queryFn:manageApi.options});const detail=useQuery({queryKey:computed(()=>['manage-package',id.value]),queryFn:()=>manageApi.package(id.value),enabled:editing});watch(()=>detail.data.value,d=>{if(d)Object.assign(form,{name:d.name,is_active:d.is_active,services:(d.services??[]).map(i=>({key:`service-${i.id??i.service_id}`,service_id:i.service_id,quantity:i.quantity,valid_days:i.valid_days}))})},{immediate:true});const serviceOptions=computed(()=>(options.data.value?.services??[]).map(s=>({label:s.name,value:s.id,disabled:!s.is_active})));const save=useMutation({mutationFn:()=>manageApi.savePackage(editing.value?id.value:null,{name:form.name,is_active:form.is_active,services:form.services.map(({service_id,quantity,valid_days})=>({service_id,quantity,valid_days}))}),onSuccess:data=>{feedback.success('权益包已保存');router.push(`/manage/packages/${data.id}`)}});const disable=useMutation({mutationFn:()=>manageApi.disablePackage(id.value),onSuccess:()=>router.push('/manage/packages')});function stop(){dialog.warning({title:'停用权益包',content:'已完成订单和已领取服务不会改变；新商品配置不再使用它。',positiveText:'确认停用',negativeText:'返回',onPositiveClick:()=>disable.mutate()})}const valid=computed(()=>Boolean(form.name.trim()&&form.services.length&&form.services.every(i=>i.service_id&&i.quantity>0&&i.valid_days>=0)))
</script><template><div class="manage-page"><LsPageHeader :title="editing?'编辑权益包':'新建权益包'" description="每一项会按数量创建互相独立的服务实例；有效天数从交付时计算。" back-to="/manage/packages" back-label="返回权益包"><template #actions><LsButton v-if="editing&&canManage('shop.product.delete')" variant="danger" @click="stop">停用权益包</LsButton></template></LsPageHeader><form class="manage-form" @submit.prevent="save.mutate()"><LsFormSection title="基本信息"><LsField label="权益包名称" for-id="package-name" required><NInput id="package-name" v-model:value="form.name" maxlength="100"/></LsField><LsSwitchField id="package-active" :model-value="form.is_active===1" label="启用状态" description="停用后不能用于新的卡活动或商品配置。" @update:model-value="v=>form.is_active=v?1:0"/></LsFormSection><LsFormSection title="服务项目"><LsFormList v-model="form.services" :item-key="i=>i.key" :create-item="make" item-label="服务" add-label="添加服务"><template #item="{item}"><div class="inline-fields"><LsField label="服务" :for-id="`package-service-${item.key}`" required><NSelect :id="`package-service-${item.key}`" v-model:value="item.service_id" :options="serviceOptions" filterable/></LsField><LsField label="数量" :for-id="`package-quantity-${item.key}`" required><NInputNumber :id="`package-quantity-${item.key}`" v-model:value="item.quantity" :min="1" :max="999"/></LsField><LsField label="有效天数" :for-id="`package-days-${item.key}`" hint="0 表示永久"><NInputNumber :id="`package-days-${item.key}`" v-model:value="item.valid_days" :min="0"/></LsField></div></template></LsFormList></LsFormSection><LsInlineError v-if="detail.isError.value" :message="friendlyError(detail.error.value)"/><LsInlineError v-if="save.isError.value" :message="friendlyError(save.error.value)"/><LsFormActions><LsButton type="button" variant="secondary" @click="router.back()">取消</LsButton><LsButton type="submit" :disabled="!valid||!canManage('shop.product.write')" :loading="save.isPending.value">保存权益包</LsButton></LsFormActions></form></div></template>
